namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics including calculus, algebra, and statistics." },
        new() { Id = "eng", Name = "English", Description = "Literature, composition, and creative writing." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events, civilizations, and cultural developments." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = "CS101", DepartmentId = "cs", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true },
        new() { Id = "CS201", DepartmentId = "cs", Title = "Data Structures & Algorithms", Description = "In-depth study of arrays, linked lists, trees, graphs, sorting, and searching algorithms with complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm design and competitive programming. Previously worked at Google Research.", IsFeatured = true },
        new() { Id = "CS301", DepartmentId = "cs", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Linda Park", InstructorBio = "Prof. Park spent a decade as a database architect at Oracle before transitioning to academia." },
        new() { Id = "CS401", DepartmentId = "cs", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, and practical applications using modern frameworks.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Michael Okafor", InstructorBio = "Dr. Okafor leads the university's AI research lab and has published over 40 papers in top ML conferences.", IsFeatured = true },
        new() { Id = "MATH101", DepartmentId = "math", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible to all students." },
        new() { Id = "MATH201", DepartmentId = "math", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Elena Vasquez", InstructorBio = "Dr. Vasquez researches applied linear algebra and numerical methods. She consults for aerospace companies on computational modeling.", IsFeatured = true },
        new() { Id = "MATH301", DepartmentId = "math", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster previously worked as a statistician at the CDC and brings real-world data analysis experience to the classroom." },
        new() { Id = "ENG101", DepartmentId = "eng", Title = "College Composition", Description = "Develop critical thinking and writing skills through essay composition, research writing, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Maria Santos", InstructorBio = "Prof. Santos is a published author and writing coach with expertise in academic and creative writing." },
        new() { Id = "ENG201", DepartmentId = "eng", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and culture.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright specializes in 20th-century American fiction and has authored two books on the Harlem Renaissance." },
        new() { Id = "PHYS101", DepartmentId = "phys", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", InstructorName = "Dr. Yuki Tanaka", InstructorBio = "Dr. Tanaka is an experimental physicist who previously worked at CERN on particle detection systems.", IsFeatured = true },
        new() { Id = "PHYS201", DepartmentId = "phys", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM + Fri Lab 2:00–4:00 PM", InstructorName = "Dr. David Nguyen", InstructorBio = "Dr. Nguyen researches quantum electrodynamics and has received multiple NSF grants for his work." },
        new() { Id = "HIST101", DepartmentId = "hist", Title = "World Civilizations", Description = "Survey of major world civilizations from ancient Mesopotamia through the early modern period.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Patricia Holmes", InstructorBio = "Dr. Holmes is an archaeologist and historian specializing in ancient Mediterranean cultures." },
        new() { Id = "HIST201", DepartmentId = "hist", Title = "Modern World History", Description = "Political, economic, and social developments from the Industrial Revolution to the present.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Prof. Richard Adekunle", InstructorBio = "Prof. Adekunle focuses on post-colonial history and global political movements of the 20th century." },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) => _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && !string.IsNullOrWhiteSpace(request.CourseId)
            && GetCourse(request.CourseId) is not null;
    }
}

