toolArgs.file_text:
@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<div class="container">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted Successfully!</h4>
            <p>Your enrollment request for <strong>@selectedCourseTitle</strong> has been received. You will be notified once it has been processed.</p>
            <a href="/courses" class="btn btn-primary">Back to Course Catalog</a>
        </div>
    }
    else
    {
        <p>Fill out the form below to submit an enrollment request.</p>

        @if (validationError is not null)
        {
            <div class="alert alert-danger">@validationError</div>
        }

        <form method="post" class="row g-3" style="max-width: 600px;">
            <AntiforgeryToken />

            <div class="col-12">
                <label for="studentName" class="form-label">Full Name</label>
                <input type="text" class="form-control" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
            </div>

            <div class="col-12">
                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" class="form-control" id="studentId" name="Model.StudentId" value="@Model.StudentId" required placeholder="e.g., STU-12345" />
            </div>

            <div class="col-12">
                <label for="courseId" class="form-label">Course</label>
                <select class="form-select" id="courseId" name="Model.CourseId" required>
                    <option value="">-- Select a course --</option>
                    @foreach (var course in CatalogService.GetCourses())
                    {
                        var dept = CatalogService.GetDepartment(course.DepartmentId);
                        <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Id - @course.Title (@dept?.Name)</option>
                    }
                </select>
            </div>

            <div class="col-12">
                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </form>
    }
</div>

@code {
    [SupplyParameterFromForm]
    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private bool submitted;
    private string? validationError;
    private string? selectedCourseTitle;

    protected override void OnInitialized()
    {
        if (!string.IsNullOrWhiteSpace(CourseId) && string.IsNullOrWhiteSpace(Model.CourseId))
        {
            Model.CourseId = CourseId;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContext.Request.Method))
        {
            if (string.IsNullOrWhiteSpace(Model.StudentName) ||
                string.IsNullOrWhiteSpace(Model.StudentId) ||
                string.IsNullOrWhiteSpace(Model.CourseId))
            {
                validationError = "All fields are required.";
                return;
            }

            var success = CatalogService.SubmitEnrollmentRequest(Model);
            if (success)
            {
                selectedCourseTitle = CatalogService.GetCourse(Model.CourseId)?.Title;
                submitted = true;
            }
            else
            {
                validationError = "Invalid enrollment request. Please check your selections and try again.";
            }
        }
    }

    [CascadingParameter]
    public HttpContext HttpContext { get; set; } = default!;
}

